scripts:
// 图腾信仰 scripts（函数式扩展：事件谓词 + 开局图腾）
// 沙箱执行：new Function('m', 'console', src)——只能调用注入的 m/console
// 祭典事件本身在 defs.events 纯声明（DLC 形态：when 谓词 + effects 效果表）
// 卡谓词（CardContext，卡 when 引用）：有图腾才抽得到祈愿卡
m.registerPredicate('hasTotem', (c) => c.view.hasBuildingWithTag?.('totem') ?? false);
// 事件谓词（SimContext，defs.events when 引用）：祭典只在有图腾时进候选池
m.registerEventPredicate('hasTotem', (ctx) => ctx.world.hasBuildingWithTag('totem'));

// 开局在营地旁放一座图腾（演示 mod 建筑出现在世界；仅铺一次）
let seeded = false;
m.registerHook('step:after', ({ sim }) => {
  if (seeded) return;
  seeded = true;
  const cx = Math.floor(sim.world.width / 2);
  const w = sim.world;
  for (let r = 3; r < 8; r++) {
    for (let dy = -r; dy <= r; dy++) {
      for (let dx = -r; dx <= r; dx++) {
        if (Math.max(Math.abs(dx), Math.abs(dy)) !== r) continue;
        const x = cx + dx;
        const y = Math.floor(sim.world.height / 2) + dy;
        if (w.canBuildFootprint(x, y, sim.mods.buildings.totem)) {
          w.placeBuilding(x, y, 'totem', 'auto');
          sim.logEvent('🗿 一座图腾矗立在营地旁');
          return;
        }
      }
    }
  }
});
